              },

              { 
                      task_name: 'denominator_neglect', 
                      custom_task_settings: 
                      {
                          task_version: 'B',
                          small_lottery_gold_coin_props: [0.2, 0.3],
                          large_lottery_gold_coin_prop_range_diff: [0.08],
                          pt_trials_n: 4,
                          pt_trials_per_block: 4,
