ranked_items &lt;- data.frame(task = as.character(),
                           item = as.character(),
                           item_cor = as.numeric(),
                           test_cor = as.numeric())


test_cor &lt;- v2_dat |&gt;
  filter(item %in% pull(ranked_items, item)) |&gt;
  summarize(.by = c(task, subject_id),
            task_score = mean(score),
            sscore = first(sscore)) |&gt;
  select(task_score, sscore) |&gt;
  cor()

highest_cor &lt;- c("start" = 0)

v2_dat |&gt;
  filter(item == "bu_h1" | item %in% pull(ranked_items, item)) |&gt;
  summarize(.by = c(task, subject_id),
            task_score = mean(score),
            sscore = first(sscore)) |&gt;
  select(task_score, sscore) |&gt;
  drop_na() |&gt;
  summarize(cor = cor(task_score, sscore)) |&gt;
  pull(cor)

if (.3 &gt; highest_cor) highest_cor &lt;- c("bu_h0" = .2)

Item Rank in Search Alg


Code
test &lt;- readRDS(here::here("Data", "Search Algorithms", "v5test_dat.rds"))


dat &lt;- dn_dat_c |&gt;
  left_join(readRDS(here::here("Data", "Denominator Neglect", "top_items.rds")) |&gt; 
            pivot_longer(c(conf_item, harm_item),
                         names_to = "choice_type", values_to = "item") |&gt;
            select(item, rank),
          by = "item") |&gt;
  mutate(item = paste0("dn.c_", item)) |&gt;
  left_join(test |&gt;
              filter(task == "dn.c") |&gt;
              # specific to denominator neglect's item pairs
              mutate(rank = as.integer(str_split_i(item, "_", 2)),
                     .keep = "unused"),
            by = "rank") |&gt;
  mutate(alg_rank = factor(rep, ordered = T),
         proportion_difference_scaled = proportion_difference * 100)

# lm(as.numeric(alg_rank) ~ proportion_difference_scaled * small_lottery_gold_prop, dat) |&gt;
#   summary()

lm(as.numeric(alg_rank) ~ proportion_difference_scaled * small_lottery_gold_prop, dat) |&gt;
  ggeffects::ggpredict(terms = c("proportion_difference_scaled", "small_lottery_gold_prop")) |&gt;
  plot() +
  theme_classic() +
  labs(title = NULL, y = "Rank from Search (R^2 / time)") +
  scale_x_continuous("Difference in Proportions", labels = scales::label_percent(scale = 1)) +
  scale_color_manual("Small Lottery Gold Proportion", 
                     values = c("0.1" = "#bbcedf", "0.2" = "#698aa4", "0.3" = "#004c6d")) +
  scale_fill_manual("Small Lottery Gold Proportion", 
                     values = c("0.1" = "#bbcedf", "0.2" = "#698aa4", "0.3" = "#004c6d")) +
  coord_cartesian(xlim = c(1, 8))

Idea: what if as a robustness check we rerun the search alg making its first item be from a specific task. Nowhere close to all possible combinations, but might be something.


Code
v5_dat |&gt; pull(task) |&gt; unique() |&gt;
  walk(\(first_task) {
    test &lt;&lt;- data.frame(first_task = "INIT",
                   rep = 0,
                   task = "INIT",
                   item = "INIT",
                   test_r2 = 0,
                   time = 0,
                   added_r2 = 0,
                   added_time = 0,
                   r2_rate = 0)

    print(first_task)

    walk(seq(1, v5_dat |&gt; pull(item) |&gt; unique() |&gt; length()), 
         \(i) {
           if (test |&gt; filter(time == max(time)) |&gt; pull(time) &gt; 10) {Sys.sleep(0)}
           else {test &lt;&lt;- v5_dat |&gt; 
             filter(!(item %in% pull(test, item))) |&gt;
             filter((i == 1 & task == first_task) | i &gt; 1) |&gt;
             pull(item) |&gt;
             unique() |&gt; 
             map(~ rbind(v5_dat |&gt;
                           filter(item == .x),
                         v5_dat |&gt;
                           filter(item %in% pull(test, item))) |&gt; 
                   summarize(.by = c(task, subject_id),
                             score = mean(score),
                             sscore = first(sscore),
                             time = sum(time),
                             task = first(task)) |&gt;
                   mutate(time = time + map_dbl(task, get_startup)) |&gt;
                   mutate(.by = subject_id,
                          time = sum(time)) |&gt; 
                   mutate(formula = paste("sscore ~", task |&gt; unique() |&gt; paste(collapse = "+"))) |&gt;
                   pivot_wider(names_from = task, values_from = score) |&gt;
                   summarize(first_task = first_task,
                             rep = i,
                             task = str_split_i(.x, "_", 1),
                             item = .x,
                             test_r2 = summary(lm(as.formula(first(formula)),
                                                  data = pick(everything())))$r.squared,
                             added_r2 = first(test_r2) - test |&gt;
                               head(1) |&gt;
                               pull(test_r2),
                             added_time = first(time) - test |&gt;
                               head(1) |&gt;
                               pull(time),
                             time = first(time),
                             r2_rate = first(added_r2 / added_time))) |&gt;
             list_rbind() |&gt;
             filter(r2_rate == max(r2_rate)) |&gt;
             rbind(test) |&gt;
             filter(item != "INIT")}
         }, 
         .progress = T)

    saveRDS(test, here::here("Data", "Search Algorithms", paste0("v5test_first-", first_task, "_dat.rds")))
  })



Code
v5_dat |&gt; pull(task) |&gt; unique() |&gt;
  walk(\(task) {
    test_firsttask &lt;- here::here("Data", "Search Algorithms",
                       paste0("v5test_first-", task, "_dat.rds")) |&gt;
      readRDS()

    (test_firsttask |&gt;
      ggplot(aes(x = time, y = test_r2)) +

      geomtextpath::geom_textsegment(data = filter(test_firsttask, test_r2 == max(test_r2)),
                                     aes(x = -Inf, xend = time, y = test_r2, yend = test_r2, label = "PEAK"),
                                     color = scales::col_lighter("#202020", amount = 35), linewidth = .3, linetype = "longdash") +
      geom_segment(data = filter(test_firsttask, test_r2 == max(test_r2)),
                   aes(y = -Inf, yend = test_r2, x = time),
                   color = scales::col_lighter("#202020", amount = 35), linewidth = .3, linetype = "longdash") +
      geom_line() +
      geom_point(aes(color = task), size = 2) +

      annotate("text", label = paste0(filter(test_firsttask, test_r2 == max(test_r2)) |&gt;
                                        pull(time) |&gt; round(1), " minutes:\n• ",
                                      test_firsttask |&gt;
                                        filter(time &lt;= filter(test_firsttask, test_r2 == max(test_r2)) |&gt;
                                                 pull(time)) |&gt;
                                        count(task) |&gt;
                                        pmap_chr(\(task, n) paste(n, task)) |&gt; 
                                        paste(collapse = "\n• ")),
               x = 26.6, y = 0.25, size = 3.4, hjust = "left", color = "#202020") +

      coord_cartesian(xlim = c(0, 20), ylim = c(0, 0.8), expand = c(0, 1)) +
      guides(x = guide_axis(cap = "both"),
             y = guide_axis(cap = "both")) +
      labs(x = "Time (minutes)", y = "Test R^2", color = "Task",
           title = paste("Starting Task: ", task)) +
      theme_classic()  +
      theme(
        panel.background = element_rect(fill='transparent'),
        plot.background = element_rect(fill='transparent', color=NA),
        panel.grid.major = element_blank(),
        panel.grid.minor = element_blank(),
        legend.background = element_blank(),
        aspect.ratio = 1)) |&gt;
      print()
  })

Mark’s idea: run with just maximizin \(R^2\) (no time in denominator)


Code
test &lt;- data.frame(rep = 0,
                   task = "INIT",
                   item = "INIT",
                   test_r2 = 0,
                   time = 0,
                   added_r2 = 0,
                   added_time = 0,
                   r2_rate = 0)

walk(seq(1, v5_dat |&gt; pull(item) |&gt; unique() |&gt; length()), 
     \(i) {test &lt;&lt;- v5_dat |&gt; 
       filter(!(item %in% pull(test, item))) |&gt;
       pull(item) |&gt;
       unique() |&gt; 
       map(~ rbind(v5_dat |&gt;
                     filter(item == .x),
                   v5_dat |&gt;
                     filter(item %in% pull(test, item))) |&gt; 
             summarize(.by = c(task, subject_id),
                       score = mean(score),
                       sscore = first(sscore),
                       time = sum(time),
                       task = first(task)) |&gt;
             mutate(time = time + map_dbl(task, get_startup)) |&gt;
             mutate(.by = subject_id,
                    time = sum(time)) |&gt; 
             mutate(formula = paste("sscore ~", task |&gt; unique() |&gt; paste(collapse = "+"))) |&gt;
             pivot_wider(names_from = task, values_from = score) |&gt;
             summarize(rep = i,
                       task = str_split_i(.x, "_", 1),
                       item = .x,
                       test_r2 = summary(lm(as.formula(first(formula)),
                                            data = pick(everything())))$r.squared,
                       added_r2 = first(test_r2) - test |&gt;
                         head(1) |&gt;
                         pull(test_r2),
                       added_time = first(time) - test |&gt;
                         head(1) |&gt;
                         pull(time),
                       time = first(time),
                       r2_rate = first(added_r2 / added_time))) |&gt;
       list_rbind() |&gt;
       # only difference is here.
       filter(added_r2 == max(added_r2)) |&gt;
       rbind(test) |&gt;
       filter(item != "INIT")}, 
     .progress = T)
test

